PROFILE_TEXT = '# Bloodborne / Dark Souls 3 style keyboard and mouse profile.\n# Combos are handled by bridge.py, not by the native input parser.\n# E = interact/confirm; Space = dodge/sprint/back; Q = lock-on.\ncross = e\ncross = enter\ncircle = space\ncircle = backspace\nsquare = r\ntriangle = c\nl1 = f\nr1 = f10\nr2 = f11\nl2 = f12\nl2 = lctrl\nl3 = z\nr3 = q\nr3 = middlebutton\noptions = escape\ntouchpad_left = g\ntouchpad_right = tab\npad_up = up\npad_down = down\npad_left = left\npad_right = right\n\naxis_left_x_minus = a\naxis_left_x_plus = d\naxis_left_y_minus = w\naxis_left_y_plus = s\nleftjoystick_halfmode = lalt\n\nmouse_to_joystick = right\nmouse_movement_params = 0.5, 1, 0.125\nmouse_camera = direct\nmouse_camera_sensitivity = 1.0\nstick_socd = last\n# Keep sprint across brief key gaps and direction changes.\n# Bloodborne uses a square movement gate: keep one axis at full deflection.\nstick_release_delay_ms = 60\nstick_circular = off\nstick_turn_rate = 900\n\n# A connected controller remains usable.\ncross = cross\ncircle = circle\nsquare = square\ntriangle = triangle\nl1 = l1\nr1 = r1\nl2 = l2\nr2 = r2\nl3 = l3\nr3 = r3\noptions = options\ntouchpad_left = back\npad_up = pad_up\npad_down = pad_down\npad_left = pad_left\npad_right = pad_right\naxis_left_x = axis_left_x\naxis_left_y = axis_left_y\naxis_right_x = axis_right_x\naxis_right_y = axis_right_y\n\nhotkey_toggle_mouse_to_joystick = f7\nhotkey_reload_inputs = f8\n'
